def longest_Consecutive(list_numbers): 
    longest_run = 0
    current_run = 0

    previous = None
    for num in list_numbers:
        if num == previous + 1:
            current_run += 1
        else:
            longest_run = max(longest_run, current_run)
            current_run = 1
        previous = num
    return max(longest_run, current_run)

