Here's some sample python code which implements task management functionality based on personal organization levels (low, medium, high). The code uses `if`/`elif` conditional blocks to determine how tasks should be prioritized depending on their level of importance. It also includes error handling and logging mechanisms to help identify potential issues and track progress over time. 

```python 
import os
from datetime import date


class TodoList:
    def __init__(self):
        self.tasks = []

    def add_task(self, description, responsibility, priority="medium"):
        new_task = {
            "description": description,
            "responsibility": responsibility,
            "priority": priority,
            "dateAdded": str(date.today()),
        }

        self.tasks.append(new_task)
        return f"{len(self.tasks)} item added."

    def get_tasks(self):
        output = ""
        for i, task in enumerate(sorted(self.tasks, key=lambda x: x["priority"])):
            output += f"Task #{i+1}: {task['description']} ({task['priority']})\n"

        return output

    def remove_task(self, index):
        try:
            del self.tasks[index]
            return f"Item removed successfully."
        except IndexError as e:
            return f"IndexError: {e}"

    def update_task(self, index, description, responsibility, priority):
        try:
            self.tasks[index] = {"description": description,
                                "responsibility": responsibility,
                                "priority": priority}

            return f"Task updated successfully."
        except IndexError as e:
            return f"IndexError: {e}"


def main():
    todo_list = TodoList()

    while True:
        print("Todo List")
        print("---------")
        print("[1] Add New Task")
        print("[2] View Tasks")
        print("[3] Remove Task")
        print("[4] Update Task")
        print("[5] Exit Program")
        choice = input("\nEnter your choice: ")

        if choice == '1':
            description = input("Description: ")
            responsibility = input("Responsibility: ")
            priority = input("Priority [high/med/low]: ").lower()
            result = todo_list.add_task(description, responsibility, priority)
            print(result)

        elif choice == '2':
            tasks = todo_list.get_tasks()
            print(tasks)

        elif choice == '3':
            index = int(input("Enter the index of the task you want to delete: "))
            result = todo_list.remove_task(index)
            print(result)

        elif choice == '4':
            index = int(input("Enter the index of the task you want to update: "))
            description = input("New Description: ")
            responsibility = input("New Responsibility: ")
            priority = input("New Priority [high/med/low]: ").lower()
            result = todo_list.update_task(index, description, responsibility, priority)
            print(result)

        else:
            break


if __name__ == "__main__":
    main()
```

def find_most_frequent(nums):
    count = {}
    max_count = 0

    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

        if count[num] > max_count:
            max_count = count[num]

    most_frequent = []
    for num, freq in count.items():
        if freq == max_count:
            most_frequent.append(num)

    most_frequent.sort(reverse=True)

    return most_frequent

